// Clone visitor
class CloneVisitor : public Visitor {
public:
    Ptr result;

    void visit(const Num& n) override {
        result = num(n.value);
    }

    void visit(const Var& n) override {
        result = var(n.name);
    }

    void visit(const Add& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = add(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Sub& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = sub(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Mul& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = mul(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Neg& n) override {
        CloneVisitor v1;
        n.a->accept(v1);
        result = neg(std::move(v1.result));
    }

    void visit(const Pow& n) override {
        CloneVisitor v1;
        n.base->accept(v1);
        result = pow_(std::move(v1.result), n.exponent);
    }

    void visit(const Exp& n) override {
        CloneVisitor v1;
        n.a->accept(v1);
        result = exp_(std::move(v1.result));
    }

    void visit(const Log& n) override {
        CloneVisitor v1;
        n.a->accept(v1);
        result = log_(std::move(v1.result));
    }

    void visit(const Div& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = div(std::move(v1.result), std::move(v2.result));
    }
};

// Fold visitor
class FoldVisitor : public Visitor {
public:
    std::unique_ptr<Node> result;

    void visit(const Num& n) override {
        result = std::make_unique<Num>(n.value);
    }

    void visit(const Var& n) override {
        result = std::make_unique<Var>(n.name);
    }

    void visit(const Add& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value + num2->value);
                return;
            }
        }

        // Simplify: x + 0, 0 + x
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 0.0) {
                result = std::move(v1.result);
                return;
            }
        }
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 0.0) {
                result = std::move(v2.result);
                return;
            }
        }

        result = std::make_unique<Add>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Sub& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value - num2->value);
                return;
            }
        }

        // Simplify: x - 0
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 0.0) {
                result = std::move(v1.result);
                return;
            }
        }

        // Simplify: 0 - x to -x
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 0.0) {
                result = neg(std::move(v2.result));
                return;
            }
        }

        result = std::make_unique<Sub>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Mul& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value * num2->value);
                return;
            }
        }

        // Simplify: x * 1, 1 * x
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 1.0) {
                result = std::move(v1.result);
                return;
            }
