        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 1.0) {
                result = std::move(v2.result);
                return;
            }
        }

        // Simplify: x * 0, 0 * x
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 0.0) {
                result = std::make_unique<Num>(0.0);
                return;
            }
        }
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 0.0) {
                result = std::make_unique<Num>(0.0);
                return;
            }
        }

        result = std::make_unique<Mul>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Neg& n) override {
        FoldVisitor v1;
        n.a->accept(v1);

