namespace ast {
// Eval visitor
class EvalVisitor : public Visitor {
public:
    const std::map<std::string, double>& env;
    double result;

    EvalVisitor(const std::map<std::string, double>& e) : env(e) {}

    void visit(const Num& n) override {
        result = n.value;
    }

    void visit(const Var& n) override {
        auto it = env.find(n.name);
        if (it == env.end()) {
            throw std::out_of_range("Unknown variable: " + n.name);
        }
        result = it->second;
    }

    void visit(const Add& n) override {
        EvalVisitor v1(env);
        EvalVisitor v2(env);
        n.a->accept(v1);
        n.b->accept(v2);
        result = v1.result + v2.result;
    }

    void visit(const Sub& n) override {
        EvalVisitor v1(env);
        EvalVisitor v2(env);
        n.a->accept(v1);
        n.b->accept(v2);
        result = v1.result - v2.result;
    }

    void visit(const Mul& n) override {
        EvalVisitor v1(env);
        EvalVisitor v2(env);
        n.a->accept(v1);
        n.b->accept(v2);
        result = v1.result * v2.result;
    }

    void visit(const Neg& n) override {
        EvalVisitor v1(env);
        n.a->accept(v1);
        result = -v1.result;
    }

    void visit(const Pow& n) override {
        EvalVisitor v1(env);
        n.base->accept(v1);
        result = std::pow(v1.result, n.exponent);
    }

    void visit(const Exp& n) override {
        EvalVisitor v1(env);
        n.a->accept(v1);
        result = std::exp(v1.result);
    }

    void visit(const Log& n) override {
        EvalVisitor v1(env);
        n.a->accept(v1);
        result = std::log(v1.result);
    }

    void visit(const Div& n) override {
        EvalVisitor v1(env);
        EvalVisitor v2(env);
        n.a->accept(v1);
        n.b->accept(v2);
        result = v1.result / v2.result;
    }
};

// Print visitor
class PrintVisitor : public Visitor {
public:
    std::string result;
    int precedence;

    PrintVisitor() : precedence(0) {}

    void visit(const Num& n) override {
        std::ostringstream oss;
        oss.precision(17);
        oss << n.value;
        result = oss.str();
        precedence = 0;
    }

    void visit(const Var& n) override {
        result = n.name;
        precedence = 0;
    }

    void visit(const Add& n) override {
        PrintVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        if (v1.precedence > 2 || (v1.precedence == 2 && v2.precedence >= 2)) {
            result = "(" + v1.result + ") + " + v2.result;
        } else {
            result = v1.result + " + " + v2.result;
        }
        precedence = 2;
    }

    void visit(const Sub& n) override {
        PrintVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        if (v1.precedence > 2 || (v1.precedence == 2 && v2.precedence >= 2)) {
            result = "(" + v1.result + ") - " + v2.result;
        } else {
            result = v1.result + " - " + v2.result;
        }
        precedence = 2;
    }

    void visit(const Mul& n) override {
        PrintVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        if (v1.precedence > 3 || (v1.precedence == 3 && v2.precedence >= 3)) {
            result = "(" + v1.result + ") * " + v2.result;
        } else {
            result = v1.result + " * " + v2.result;
        }
        precedence = 3;
    }

    void visit(const Neg& n) override {
        PrintVisitor v1;
        n.a->accept(v1);
        if (v1.precedence > 1) {
            result = "-(" + v1.result + ")";
        } else {
            result = "-" + v1.result;
        }
        precedence = 1;
    }

    void visit(const Pow& n) override {
        PrintVisitor v1;
        n.base->accept(v1);
        std::ostringstream oss;
        oss.precision(17);
        oss << n.exponent;
        result = v1.result + "^" + oss.str();
        precedence = 4;
    }

    void visit(const Exp& n) override {
        PrintVisitor v1;
        n.a->accept(v1);
        result = "exp(" + v1.result + ")";
        precedence = 0;
    }

    void visit(const Log& n) override {
        PrintVisitor v1;
        n.a->accept(v1);
        result = "log(" + v1.result + ")";
        precedence = 0;
    }

    void visit(const Div& n) override {
        PrintVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = v1.result + " / " + v2.result;
        precedence = 3; // Division has same precedence as multiplication
    }
};

// Vars visitor
class VarsVisitor : public Visitor {
public:
    std::set<std::string> result;

    void visit(const Num& n) override {
        // Nothing to do for numbers
    }

    void visit(const Var& n) override {
        result.insert(n.name);
    }

    void visit(const Add& n) override {
        VarsVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result.insert(v1.result.begin(), v1.result.end());
        result.insert(v2.result.begin(), v2.result.end());
    }

    void visit(const Sub& n) override {
        VarsVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result.insert(v1.result.begin(), v1.result.end());
        result.insert(v2.result.begin(), v2.result.end());
    }

    void visit(const Mul& n) override {
        VarsVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result.insert(v1.result.begin(), v1.result.end());
        result.insert(v2.result.begin(), v2.result.end());
    }

    void visit(const Neg& n) override {
        VarsVisitor v1;
        n.a->accept(v1);
        result.insert(v1.result.begin(), v1.result.end());
    }

    void visit(const Pow& n) override {
        VarsVisitor v1;
        n.base->accept(v1);
        result.insert(v1.result.begin(), v1.result.end());
    }

    void visit(const Exp& n) override {
        VarsVisitor v1;
        n.a->accept(v1);
        result.insert(v1.result.begin(), v1.result.end());
    }

    void visit(const Log& n) override {
        VarsVisitor v1;
        n.a->accept(v1);
        result.insert(v1.result.begin(), v1.result.end());
    }

    void visit(const Div& n) override {
        VarsVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result.insert(v1.result.begin(), v1.result.end());
        result.insert(v2.result.begin(), v2.result.end());
    }
};

// Clone visitor
class CloneVisitor : public Visitor {
public:
    std::unique_ptr<Node> result;

    void visit(const Num& n) override {
        result = std::make_unique<Num>(n.value);
    }

    void visit(const Var& n) override {
        result = std::make_unique<Var>(n.name);
    }

    void visit(const Add& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Add>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Sub& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Sub>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Mul& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Mul>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Neg& n) override {
        CloneVisitor v1;
        n.a->accept(v1);
        result = std::make_unique<Neg>(std::move(v1.result));
    }

    void visit(const Pow& n) override {
        CloneVisitor v1;
        n.base->accept(v1);
        result = std::make_unique<Pow>(std::move(v1.result), n.exponent);
    }

    void visit(const Exp& n) override {
        CloneVisitor v1;
        n.a->accept(v1);
        result = std::make_unique<Exp>(std::move(v1.result));
    }

    void visit(const Log& n) override {
        CloneVisitor v1;
        n.a->accept(v1);
        result = std::make_unique<Log>(std::move(v1.result));
    }

    void visit(const Div& n) override {
        CloneVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Div>(std::move(v1.result), std::move(v2.result));
    }
};

// Fold visitor
class FoldVisitor : public Visitor {
public:
    std::unique_ptr<Node> result;

    void visit(const Num& n) override {
        result = std::make_unique<Num>(n.value);
    }

    void visit(const Var& n) override {
        result = std::make_unique<Var>(n.name);
    }

    void visit(const Add& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value + num2->value);
                return;
            }
        }

        // Simplify: x + 0, 0 + x
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 0.0) {
                result = std::move(v1.result);
                return;
            }
        }
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 0.0) {
                result = std::move(v2.result);
                return;
            }
        }

        result = std::make_unique<Add>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Sub& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value - num2->value);
                return;
            }
        }

        // Simplify: x - 0
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 0.0) {
                result = std::move(v1.result);
                return;
            }
        }

        // Simplify: 0 - x to -x
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 0.0) {
                result = std::make_unique<Neg>(std::move(v2.result));
                return;
            }
        }

        result = std::make_unique<Sub>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Mul& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value * num2->value);
                return;
            }
        }

        // Simplify: x * 1, 1 * x
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 1.0) {
                result = std::move(v1.result);
                return;
            }
        }
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 1.0) {
                result = std::move(v2.result);
                return;
            }
        }

        // Simplify: x * 0, 0 * x
        if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
            if (num2->value == 0.0) {
                result = std::make_unique<Num>(0.0);
                return;
            }
        }
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (num1->value == 0.0) {
                result = std::make_unique<Num>(0.0);
                return;
            }
        }

        result = std::make_unique<Mul>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Neg& n) override {
        FoldVisitor v1;
        n.a->accept(v1);

        // Try to evaluate if it's a number
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            result = std::make_unique<Num>(-num1->value);
            return;
        }

        // Simplify: -(-x) to x
        if (auto* neg1 = dynamic_cast<Neg*>(v1.result.get())) {
            result = std::move(neg1->a);
            return;
        }

        result = std::make_unique<Neg>(std::move(v1.result));
    }

    void visit(const Pow& n) override {
        FoldVisitor v1;
        n.base->accept(v1);

        // Try to evaluate if base is a number
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            result = std::make_unique<Num>(std::pow(num1->value, n.exponent));
            return;
        }

        // Simplify: x^1, x^0
        if (n.exponent == 1.0) {
            result = std::move(v1.result);
            return;
        }
        if (n.exponent == 0.0) {
            result = std::make_unique<Num>(1.0);
            return;
        }

        result = std::make_unique<Pow>(std::move(v1.result), n.exponent);
    }

    void visit(const Exp& n) override {
        FoldVisitor v1;
        n.a->accept(v1);

        // Try to evaluate if it's a number
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            result = std::make_unique<Num>(std::exp(num1->value));
            return;
        }

        result = std::make_unique<Exp>(std::move(v1.result));
    }

    void visit(const Log& n) override {
        FoldVisitor v1;
        n.a->accept(v1);

        // Try to evaluate if it's a number
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            result = std::make_unique<Num>(std::log(num1->value));
            return;
        }

        result = std::make_unique<Log>(std::move(v1.result));
    }

    void visit(const Div& n) override {
        FoldVisitor v1, v2;
        n.a->accept(v1);
        n.b->accept(v2);

        // Try to evaluate if both are numbers
        if (auto* num1 = dynamic_cast<Num*>(v1.result.get())) {
            if (auto* num2 = dynamic_cast<Num*>(v2.result.get())) {
                result = std::make_unique<Num>(num1->value / num2->value);
                return;
            }
        }

        result = std::make_unique<Div>(std::move(v1.result), std::move(v2.result));
    }
};

// Diff visitor
class DiffVisitor : public Visitor {
public:
    const std::string& var;
    std::unique_ptr<Node> result;

    DiffVisitor(const std::string& v) : var(v) {}

    void visit(const Num& n) override {
        result = std::make_unique<Num>(0.0);
    }

    void visit(const Var& n) override {
        if (n.name == var) {
            result = std::make_unique<Num>(1.0);
        } else {
            result = std::make_unique<Num>(0.0);
        }
    }

    void visit(const Add& n) override {
        DiffVisitor v1(var);
        DiffVisitor v2(var);
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Add>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Sub& n) override {
        DiffVisitor v1(var);
        DiffVisitor v2(var);
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Sub>(std::move(v1.result), std::move(v2.result));
    }

    void visit(const Mul& n) override {
        DiffVisitor v1(var);
        DiffVisitor v2(var);
        n.a->accept(v1);
        n.b->accept(v2);
        result = std::make_unique<Add>(std::make_unique<Mul>(std::move(v1.result), n.b->clone()), 
                                       std::make_unique<Mul>(n.a->clone(), std::move(v2.result)));
    }

    void visit(const Neg& n) override {
        DiffVisitor v1(var);
        n.a->accept(v1);
        result = std::make_unique<Neg>(std::move(v1.result));
    }

    void visit(const Pow& n) override {
        if (n.exponent == 0.0) {
            result = std::make_unique<Num>(0.0);
        } else if (n.exponent == 1.0) {
            DiffVisitor v1(var);
            n.base->accept(v1);
            result = std::move(v1.result);
        } else {
            // For u^n, derivative is n*u^(n-1)*u'
            DiffVisitor v1(var);
            n.base->accept(v1);
            result = std::make_unique<Mul>(std::make_unique<Num>(n.exponent), 
                                           std::make_unique<Mul>(std::make_unique<Pow>(n.base->clone(), n.exponent - 1), 
                                                                 std::move(v1.result)));
        }
    }

    void visit(const Exp& n) override {
        DiffVisitor v1(var);
        n.a->accept(v1);
        // Derivative of exp(u) is exp(u)*u'
        result = std::make_unique<Mul>(std::make_unique<Exp>(n.a->clone()), std::move(v1.result));
    }

    void visit(const Log& n) override {
        DiffVisitor v1(var);
        n.a->accept(v1);
        // Derivative of log(u) is 1/u*u'
        result = std::make_unique<Div>(std::move(v1.result), n.a->clone());
    }

    void visit(const Div& n) override {
        DiffVisitor v1(var);
        DiffVisitor v2(var);
        n.a->accept(v1);
        n.b->accept(v2);
        // Derivative of (u/v) is (u'*v - u*v')/(v^2)
        result = std::make_unique<Div>(std::make_unique<Sub>(std::make_unique<Mul>(std::move(v1.result), n.b->clone()), 
                                                             std::make_unique<Mul>(n.a->clone(), std::move(v2.result))), 
                                       std::make_unique<Pow>(n.b->clone(), 2.0));
    }
};

// Free functions implementation
std::unique_ptr<Node> num(double v) {
    return std::make_unique<Num>(v);
}

std::unique_ptr<Node> var(std::string name) {
    return std::make_unique<Var>(std::move(name));
}

std::unique_ptr<Node> add(std::unique_ptr<Node> a, std::unique_ptr<Node> b) {
    return std::make_unique<Add>(std::move(a), std::move(b));
}

std::unique_ptr<Node> sub(std::unique_ptr<Node> a, std::unique_ptr<Node> b) {
    return std::make_unique<Sub>(std::move(a), std::move(b));
}

std::unique_ptr<Node> mul(std::unique_ptr<Node> a, std::unique_ptr<Node> b) {
    return std::make_unique<Mul>(std::move(a), std::move(b));
}

std::unique_ptr<Node> div(std::unique_ptr<Node> a, std::unique_ptr<Node> b) {
    return std::make_unique<Div>(std::move(a), std::move(b));
}

std::unique_ptr<Node> neg(std::unique_ptr<Node> a) {
    return std::make_unique<Neg>(std::move(a));
}

std::unique_ptr<Node> pow_(std::unique_ptr<Node> base, double exponent) {
    return std::make_unique<Pow>(std::move(base), exponent);
}

std::unique_ptr<Node> exp_(std::unique_ptr<Node> a) {
    return std::make_unique<Exp>(std::move(a));
}

std::unique_ptr<Node> log_(std::unique_ptr<Node> a) {
    return std::make_unique<Log>(std::move(a));
}

double eval(const Node& n, const std::map<std::string, double>& env) {
    EvalVisitor v(env);
    n.accept(v);
    return v.result;
}

std::string print(const Node& n) {
    PrintVisitor v;
    n.accept(v);
    return v.result;
}

std::set<std::string> vars(const Node& n) {
    VarsVisitor v;
    n.accept(v);
    return v.result;
}

std::unique_ptr<Node> clone(const Node& n) {
    CloneVisitor v;
    n.accept(v);
    return std::move(v.result);
}

std::unique_ptr<Node> fold(const Node& n) {
    // Apply fold until no more changes
    std::unique_ptr<Node> current = clone(n);
    std::unique_ptr<Node> next;
    bool changed = true;
    while (changed) {
        changed = false;
        FoldVisitor v;
        current->accept(v);
        next = std::move(v.result);
        // Check if there's a change
        if (next.get() != current.get()) {
            changed = true;
            current = std::move(next);
        }
    }
    return current;
}

std::unique_ptr<Node> diff(const Node& n, const std::string& x) {
    DiffVisitor v(x);
    n.accept(v);
    return std::move(v.result);
}
